          $terraData.srOnStaff(s) &&
          $terraData.srRhodesPost(s, "本艦") &&
          s.year - lastPostingChange >= 3 &&
          ["クルビア", "ヴィクトリア", "ウルサス", "龍門", "リターニア", "サルゴン", "イベリア", "ボリバル"].includes(
            s.res?.n
          )
        );
